import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";

export function inspectRetired(root: string) {
  const rawCurrentProductPath = join(root, "userdata", "stores", "product.sqlite");
  const database = new DatabaseSync(rawCurrentProductPath);
  database.exec("DELETE FROM product_entries");
  database.close();
}
